#include <bits/stdc++.h>
using namespace std;

int main() {
    int n = 3, m = 4;
    vector<vector<int>> g(n, vector<int>(m));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) g[i][j] = i * m + j;
    long long total = 0;
    for (const auto &row : g) {
        for (int j = 0; j < m; j++) cout << row[j] << (j + 1 < m ? ' ' : '\n');
        total += accumulate(row.begin(), row.end(), 0LL);
    }
    cout << total << '\n';
    for (int i = 0; i < n; i++) cout << g[i][1] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> a;
    int x;
    while (cin >> x) a.push_back(x);
    int idx = max_element(a.begin(), a.end()) - a.begin();
    cout << a[idx] << ' ' << idx << '\n';  // 처음 나오는 위치(0부터)
    int last = -1;
    for (int i = 0; i < (int)a.size(); i++)
        if (a[i] == a[idx]) last = i;
    cout << last << '\n';  // 마지막 위치
    reverse(a.begin() + 0, a.begin() + 3);
    for (int i = 0; i < (int)a.size(); i++) cout << a[i] << (i + 1 < (int)a.size() ? ' ' : '\n');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

void print(const vector<int> &v) {
    for (int x : v) cout << x << ' ';
    cout << '\n';
}

